'use client'

import * as React from 'react'
import { ArrowDown, WarningCircle } from 'iconoir-react'
import { Badge, type BadgeTone } from '@/registry/satin/ui/badge'
import { Button } from '@/registry/satin/ui/button'
import { ChartCard, ChartTooltip, glideAnchor, useGlide, type ChartCardBaseProps, type ChartTooltipRow, type GlidePoint } from '@/registry/satin/ui/chart'
import { EmptyState } from '@/registry/satin/ui/empty-state'
import { useSatinLabels } from '@/registry/satin/ui/labels'
import { cn } from '@/lib/utils'
import { Skeleton } from '@/registry/satin/ui/skeleton'

/**
 * FunnelChart: a conversion funnel through stages (recruiting, sales, checkout), in the chart
 * card frame (Free's `ChartCard`: title, range, an optional KPI and period Select).
 *
 * - The shape: one chart/3 flow, centred, its thickness each stage's share of the first stage to
 *   the power 0.35 (a quarter of the first draws 62% as thick, 1% draws 20%), so the middle
 *   stages stay full and only a very small share draws thin, easing on an S-curve from one
 *   stage's thickness to the next's across the stage. The last stage closes it to a sharp point:
 *   flat out of the stage before, then narrowing faster and faster into a long, hyperbolic tip.
 *   Horizontal (default) flows left to right,
 *   one column per stage, its words on top: the label and the count, with its share of the first
 *   when `showConversion` asks for it. Vertical flows top to bottom, one row per stage, its words
 *   at the start. The stages join edge to edge into one flow, with no line between them; the
 *   stage on show lights up its whole area (bg-hover) and the other stages' shapes fade to 30% of
 *   their colour, as BarChart's other bars do.
 * - The step between two stages sits under the piece of the flow that narrows, centred on the
 *   stage it leaves (after it and level with its middle, vertical): the share lost on the way, muted, after a down arrow ("↓ 75%"). A drop-off of at
 *   least `dropOffWarning` (default half the previous stage) puts the words "big drop-off" in
 *   the stage's name and the table; the drawing shows it as any other step.
 *   `showConversion="first"` leaves the steps out. A stage of 0 keeps its column; the flow
 *   closes to a point before it.
 * - On first appearance each stage's shape fades in from 95% of its thickness (opacity and
 *   transform, 250 ms on ease-out, 25 ms apart, at most four steps), never from zero; none under
 *   reduced motion or with `reducedMotion`. New values swap in place.
 * - Hover and keyboard focus show the stage in a ChartTooltip card (its label, its count and
 *   drop-off as rows, its conversions in a muted line), beside the column over the next stage's
 *   flow (before it for the last stage), above the row when vertical: never over the words. After the
 *   pointer it glides from stage to stage (`useGlide`), under the keyboard it jumps. The funnel
 *   is one tab stop (roving tab index): ↑ ↓ (and ← → in reading order) move between stages,
 *   Home and End jump. With `onStageSelect` every stage is a button (Enter, Space); without, a
 *   focusable list item that only shows the tooltip.
 * - Every stage is named in words: "Interview: 18, 30% of Screening, 7.5% of Applied,
 *   drop-off 42". A table with the same rows (`FunnelTable`) is in the DOM, visually hidden,
 *   and shown with `showTable`.
 * - `loading`, empty `stages`, and `error` keep the height of five stages: Skeleton rows, an
 *   EmptyState, or the reason as a polite status with Retry when `onRetry` is given.
 * - Counts and percentages are written with `Intl.NumberFormat` in the labels' `dateLocale`;
 *   `format` writes counts another way (currency).
 *
 * Parts: `FunnelChartStage` (one stage's drawing), `FunnelTable`, `funnelRows` (the numbers both
 * read) and `funnelShapePath`. Other props, `ref` included, go to the card's root `div`.
 */

/** The words the Funnel chart says on its own. They join SatinLabels, so the app translates them there. */
export const funnelChartLabels = {
  /** A conversion: "30% of Screening". */
  funnelOf: (percent: string, stage: string) => `${percent} of ${stage}`,
  /** The people (or deals) lost since the previous stage: "drop-off 42". */
  funnelDropOff: (count: string) => `drop-off ${count}`,
  /** Read after a drop-off of at least `dropOffWarning`. */
  funnelBigDropOff: 'big drop-off',
  /** A stage's name: "Interview: 18, 30% of Screening, 7.5% of Applied, drop-off 42". */
  funnelStageName: (stage: string, value: string, details: string[]) => [`${stage}: ${value}`, ...details].join(', '),
  /** The empty state's title when `empty` isn't given. */
  funnelNoData: 'No data',
  /** Read while the funnel loads. */
  funnelLoading: 'Loading',
  /** Shown for `error={true}`. */
  funnelError: "Couldn't load",
  funnelRetry: 'Retry',
  /** The table's column heads. */
  funnelStage: 'Stage',
  funnelCount: 'Count',
  funnelFromPrevious: 'From previous',
  funnelFromFirst: 'From first',
  funnelDropOffHead: 'Drop-off',
}

type FunnelChartLabels = typeof funnelChartLabels
declare module '@/components/ui/labels' {
  interface SatinLabelSet extends FunnelChartLabels {}
}

const useLabels = () => {
  const labels = useSatinLabels()
  return React.useMemo(() => ({ ...funnelChartLabels, ...labels }), [labels])
}
type Labels = ReturnType<typeof useLabels>

/* ---------- numbers ---------- */

export type FunnelStage = {
  label: string
  value: number
  /** Emphasis for one stage: its bar takes the tone's colour, one of Badge's tones. */
  tone?: BadgeTone
}

export type FunnelConversion = 'previous' | 'first' | 'both'

/** One stage with what the funnel says about it. Shares are 0–1; `null` where there's nothing to divide by. */
export type FunnelRow = FunnelStage & {
  index: number
  /** The bar's length: the stage's share of the first stage, 0–1. */
  share: number
  /** Conversion from the previous stage; `null` for the first stage or after a stage of 0. */
  fromPrevious: number | null
  /** Conversion from the first stage; `null` for the first stage or when it is 0. */
  fromFirst: number | null
  /** How many were lost since the previous stage (never below 0); `null` for the first. */
  dropOff: number | null
  /** The share of the previous stage lost, 0–1; `null` where `fromPrevious` is. */
  dropOffShare: number | null
  /** The drop-off share reached `dropOffWarning`. */
  bigDropOff: boolean
  /** The previous stage's label, for "30% of Screening". */
  previousLabel?: string
  firstLabel: string
}

/**
 * The numbers the bars and the table read: each stage's share of the first, the conversions and
 * the drop-off. A value that isn't finite or is below 0 counts as 0. Exported for funnels of your own.
 */
export function funnelRows(stages: FunnelStage[], dropOffWarning = 0.5): FunnelRow[] {
  const values = stages.map((s) => (Number.isFinite(s.value) && s.value > 0 ? s.value : 0))
  const first = values[0] ?? 0
  return stages.map((stage, i) => {
    const value = values[i]
    const prev = i > 0 ? values[i - 1] : null
    const fromPrevious = prev ? value / prev : null
    const dropOffShare = fromPrevious == null ? null : Math.max(0, 1 - fromPrevious)
    return {
      ...stage,
      value,
      index: i,
      share: first ? Math.min(1, value / first) : 0,
      fromPrevious,
      fromFirst: i > 0 && first ? value / first : null,
      dropOff: prev == null ? null : Math.max(0, prev - value),
      dropOffShare,
      bigDropOff: dropOffShare != null && dropOffShare > 0 && dropOffShare >= dropOffWarning,
      previousLabel: i > 0 ? stages[i - 1].label : undefined,
      firstLabel: stages[0].label,
    }
  })
}

type Formatters = { count: (v: number) => string; percent: (v: number) => string }

function useFormatters(labels: Labels, format?: (value: number) => string): Formatters {
  return React.useMemo(() => {
    const count = new Intl.NumberFormat(labels.dateLocale)
    const percent = new Intl.NumberFormat(labels.dateLocale, { style: 'percent', maximumFractionDigits: 1 })
    return { count: format ?? ((v) => count.format(v)), percent: (v) => percent.format(v) }
  }, [labels.dateLocale, format])
}

const showsPrevious = (c: FunnelConversion) => c !== 'first'
const showsFirst = (c: FunnelConversion) => c !== 'previous'

/** The stage in words, for its name and its tooltip. */
function stageDetails(row: FunnelRow, labels: Labels, fmt: Formatters, conversion: FunnelConversion) {
  const details: string[] = []
  if (showsPrevious(conversion) && row.fromPrevious != null && row.previousLabel != null)
    details.push(labels.funnelOf(fmt.percent(row.fromPrevious), row.previousLabel))
  // The name says the share of the first whatever the column shows: the tooltip does too.
  if (row.fromFirst != null && !(row.index === 1 && showsPrevious(conversion))) details.push(labels.funnelOf(fmt.percent(row.fromFirst), row.firstLabel))
  if (row.dropOff != null) details.push(labels.funnelDropOff(fmt.count(row.dropOff)))
  if (row.bigDropOff) details.push(labels.funnelBigDropOff)
  return details
}

/**
 * The tooltip's second line, under the stage's label: the count, its share of the first ("7.5% of Applied") and the drop-off
 * ("drop-off 42"), what the column doesn't say. The first stage's is the count alone. Short, so
 * it fits a phone; the name and the table say the rest.
 */
/**
 * The tooltip card: the stage on top, its count in the flow's colour and the people lost since the
 * previous stage, then its conversions in a muted line ("30% of Screening · 7.5% of Applied").
 */
function tooltipContent(row: FunnelRow, labels: Labels, fmt: Formatters) {
  const rows: ChartTooltipRow[] = [
    { color: row.tone ? 'var(--sa-tone-fg)' : 'var(--sa-chart-3)', label: labels.funnelCount, value: fmt.count(row.value) },
  ]
  if (row.dropOff != null) rows.push({ color: 'var(--sa-border-strong)', label: labels.funnelDropOffHead, value: fmt.count(row.dropOff) })
  const note = [
    row.fromPrevious != null ? labels.funnelOf(fmt.percent(row.fromPrevious), row.previousLabel ?? '') : null,
    row.fromFirst != null && row.index > 1 ? labels.funnelOf(fmt.percent(row.fromFirst), row.firstLabel) : null,
  ].filter(Boolean)
  return { rows, note: note.length ? note.join(' · ') : undefined }
}

/**
 * The step from the previous stage, under the flow: the share lost on the way ("↓ 75%"), muted.
 * After a stage of 0 it says "—". A big drop-off looks the same: its stage's name says it.
 */
function StepDrop({ row, fmt }: { row: FunnelRow; fmt: Formatters }) {
  return (
    <span
      data-slot="funnel-chart-step"
      data-warning={row.bigDropOff || undefined}
      className="sa:flex sa:items-center sa:gap-1 sa:text-sm sa:leading-(--sa-text-sm--line-height) sa:whitespace-nowrap sa:text-text-muted sa:tabular-nums sa:[&_svg]:size-icon-size-sm sa:[&_svg]:shrink-0"
    >
      <ArrowDown />
      {row.fromPrevious != null ? fmt.percent(1 - row.fromPrevious) : '—'}
    </span>
  )
}

/* ---------- one stage ---------- */

export interface FunnelChartStageProps extends Omit<React.ComponentProps<'span'>, 'children'> {
  row: FunnelRow
  /** The next stage's share of the first (0–1): the shape eases to it across the stage. Default: the stage's own, flat. */
  nextShare?: number
  orientation?: 'horizontal' | 'vertical'
  showConversion?: FunnelConversion
  /** Writes the count. Default: the number in `dateLocale`. */
  format?: (value: number) => string
  /** This stage is on show: its area lights up. */
  active?: boolean
  /** Another stage is on show: the shape fades to 30% of its colour on the card, as BarChart's other bars do. */
  dimmed?: boolean
  /** Fades the shape in from 95% of its thickness, once, when it mounts. */
  enter?: boolean
  /** The next stage: under this one (after it, vertical) the step says the share lost on the way there, where the flow narrows. */
  next?: FunnelRow
}

// The thickness is the share to the power 0.35: a straight share narrows so fast that the middle
// of a hiring funnel (2–25% of the first stage) is a thread. Only a very small share draws thin.
// Its words and the table give the true share. A stage that isn't 0 stays at least 3% thick
// (6px of the 200px shape).
const CURVE = 0.35
const MIN_THICK = 0.03
const thick = (share: number) => (share > 0 ? Math.max(share ** CURVE, MIN_THICK) : 0)
// The shape's edges, in a 0–100 box: centred on the flow's axis.
const near = (share: number) => 50 - thick(share) * 50
const far = (share: number) => 50 + thick(share) * 50
const n2 = (v: number) => Math.round(v * 100) / 100

/**
 * The shape for one stage, in a 100 × 100 box drawn to its cell: the stage's share of the first
 * to the power 0.35 as its thickness (at least 3% when it isn't 0), centred, easing on an S-curve to the next
 * stage's by the cell's far end.
 * Cells side by side join into one flowing funnel. `vertical` flows top to bottom.
 *
 * When the next share is 0 (after the last stage, or before a stage of 0) the shape closes to a
 * point instead: it leaves its thickness flat, so it joins the stage before without a kink, then
 * narrows faster and faster and runs into the axis on a long, almost flat curve, like a hyperbola
 * meeting its asymptote. The tip is always an acute angle, however thick the stage is.
 */
export function funnelShapePath(share: number, nextShare: number, vertical = false) {
  const [a1, a2, b1, b2] = [near(share), far(share), near(nextShare), far(nextShare)].map(n2)
  if (nextShare <= 0 && share > 0) {
    // Control points: flat out of the stage, then 92% of the way to the axis by a third of the cell.
    const [c1, c2] = [n2(50 - (50 - a1) * 0.08), n2(50 + (a2 - 50) * 0.08)]
    return vertical
      ? `M ${a1} 0 C ${a1} 25 ${c1} 35 50 100 C ${c2} 35 ${a2} 25 ${a2} 0 Z`
      : `M 0 ${a1} C 25 ${a1} 35 ${c1} 100 50 C 35 ${c2} 25 ${a2} 0 ${a2} Z`
  }
  return vertical
    ? `M ${a1} 0 C ${a1} 50 ${b1} 50 ${b1} 100 L ${b2} 100 C ${b2} 50 ${a2} 50 ${a2} 0 Z`
    : `M 0 ${a1} C 50 ${a1} 50 ${b1} 100 ${b1} L 100 ${b2} C 50 ${b2} 50 ${a2} 0 ${a2} Z`
}

/**
 * One stage's drawing, hidden from screen readers (the stage that holds it carries its name). The
 * words on top (horizontal) or at the start (vertical): the label and the count, with its share
 * of the first when `showConversion` is `'first'` or `'both'` (not on the first stage). Then its piece of the funnel: a
 * chart/3 shape whose thickness follows its share of the first, edge to edge, easing to the next
 * stage's. With `active` its whole area lights up.
 *
 * Under the shape (horizontal), centred on the stage, or after it (vertical), level with its
 * middle, sits the step to the `next` stage (`[data-slot="funnel-chart-step"]`, not on the last
 * stage, nor with `showConversion="first"`): the share lost on the way ("↓ 75%"), under the
 * piece of the flow that narrows.
 *
 * The tooltip points at `[data-slot="funnel-chart-marker"]`, level with the middle of the shape:
 * at the column's end (its start on the last stage) or, vertical, at the middle of the row, so it
 * never covers the words.
 * Spans only, so it can sit in a button. Other props, `ref` included, go to its root `span`.
 */
export function FunnelChartStage({
  row,
  nextShare,
  orientation = 'horizontal',
  showConversion = 'previous',
  format,
  active = false,
  dimmed = false,
  enter = false,
  next: nextRow,
  className,
  ...props
}: FunnelChartStageProps) {
  const labels = useLabels()
  const fmt = useFormatters(labels, format)
  const vertical = orientation === 'vertical'
  // The last stage closes the funnel to a point.
  const next = nextShare ?? nextRow?.share ?? 0
  const first = showsFirst(showConversion) && row.index > 0 && row.fromFirst != null ? fmt.percent(row.fromFirst) : null
  const step = nextRow != null && showsPrevious(showConversion)

  const words = (
    <span
      className={cn(
        'sa:flex sa:min-w-0 sa:flex-col sa:text-sm sa:leading-(--sa-text-sm--line-height)',
        vertical ? 'sa:w-40 sa:shrink-0 sa:justify-center sa:ps-3 sa:pe-4' : 'sa:px-3 sa:pt-2 sa:pb-5',
      )}
    >
      <span className="sa:block sa:h-5 sa:truncate sa:text-text-muted">{row.label}</span>
      <span className="sa:flex sa:h-7 sa:min-w-0 sa:items-baseline sa:gap-1.5 sa:overflow-hidden sa:whitespace-nowrap sa:tabular-nums">
        <span className="sa:text-lg sa:leading-7 sa:font-semibold sa:text-text-default">{fmt.count(row.value)}</span>
        {first && <span className="sa:min-w-0 sa:truncate sa:text-text-muted">{first}</span>}
      </span>
    </span>
  )

  // Under the flow, centred on the stage (horizontal), or after it, level with its middle.
  const stepRow = (
    <span className={cn('sa:flex sa:shrink-0 sa:items-center', vertical ? 'sa:ms-4 sa:w-20' : 'sa:h-8 sa:justify-center')}>
      {step && <StepDrop row={nextRow} fmt={fmt} />}
    </span>
  )

  return (
    <span
      aria-hidden
      data-slot="funnel-chart-stage"
      data-orientation={orientation}
      className={cn(
        'sa:flex sa:min-w-0 sa:rounded-md sa:transition-colors sa:duration-(--sa-duration-fast) sa:ease-(--sa-ease-out)',
        !vertical && 'sa:flex-col',
        // The stage on show: its whole area lights up.
        active && 'sa:bg-bg-hover',
        className,
      )}
      {...props}
    >
      {words}
      <span className={cn('sa:relative sa:block', vertical ? 'sa:h-22 sa:min-w-0 sa:flex-1' : 'sa:h-40')}>
        <svg
          data-slot="funnel-chart-shape"
          data-orientation={orientation}
          data-tone={row.tone}
          data-enter={enter || undefined}
          viewBox="0 0 100 100"
          preserveAspectRatio="none"
          className={cn(
            'sa:absolute sa:block sa:overflow-visible',
            // Edge to edge, so the stages join into one flow; 1px over the next stage, so no seam shows.
            vertical ? 'sa:inset-x-0 sa:top-0 sa:w-full' : 'sa:inset-y-0 sa:start-0 sa:h-full sa:rtl:-scale-x-100',
            row.tone ? 'sa:text-tone-fg' : 'sa:text-chart-3',
            'sa:transition-colors sa:duration-(--sa-duration-fast) sa:ease-(--sa-ease-out)',
          )}
          // Five steps at most, so a long funnel doesn't keep its last stages waiting.
          // Dimmed in a solid mix with the card, never with opacity: the shapes overlap by 1px and a
          // see-through overlap would draw a seam.
          style={{
            color: dimmed ? (row.tone ? 'color-mix(in oklab, var(--sa-tone-fg) 30%, var(--sa-bg-card))' : 'color-mix(in oklab, var(--sa-chart-3) 30%, var(--sa-bg-card))') : undefined,
            animationDelay: enter ? `${Math.min(row.index, 4) * 25}ms` : undefined,
            ...(vertical ? { height: 'calc(100% + 1px)' } : { width: 'calc(100% + 1px)' }),
          }}
        >
          <path d={funnelShapePath(row.share, next, vertical)} fill="currentColor" />
        </svg>
        <span
          data-slot="funnel-chart-marker"
          // Left to right the card sits beside the column, over the flow next to it: after the column,
          // before it for the last stage.
          className={cn('sa:absolute sa:size-0', vertical ? 'sa:start-1/2' : nextRow ? 'sa:end-0' : 'sa:start-0')}
          style={{ top: '50%' }}
        />
      </span>
      {stepRow}
    </span>
  )
}

/* ---------- table ---------- */

export interface FunnelTableProps extends Omit<React.ComponentProps<'table'>, 'children'> {
  stages: FunnelStage[]
  /** The table's caption, the chart's title. */
  caption?: string
  format?: (value: number) => string
  /** Shown on the page; otherwise only screen readers get it. */
  visible?: boolean
  /** Share of the previous stage lost that marks a big drop-off. Default 0.5. */
  dropOffWarning?: number
}

/**
 * The funnel as a table: stage, count, from previous, from first, drop-off. The Funnel chart
 * renders one, visually hidden unless `showTable`. Other props, `ref` included, go to the `table`.
 */
export function FunnelTable({ stages, caption, format, visible = false, dropOffWarning = 0.5, className, ...props }: FunnelTableProps) {
  const labels = useLabels()
  const fmt = useFormatters(labels, format)
  const rows = React.useMemo(() => funnelRows(stages, dropOffWarning), [stages, dropOffWarning])
  const cell = 'sa:h-9 sa:border-t sa:border-border-default sa:px-2 sa:text-end sa:tabular-nums sa:whitespace-nowrap'
  const pct = (v: number | null) => (v == null ? '—' : fmt.percent(v))
  return (
    <table
      data-slot="funnel-table"
      className={cn(visible ? 'sa:w-full sa:border-collapse sa:text-sm sa:leading-(--sa-text-sm--line-height) sa:text-text-default' : 'sa:sr-only', className)}
      {...props}
    >
      {caption && <caption className="sa:sr-only">{caption}</caption>}
      <thead>
        <tr className="sa:text-text-muted">
          <th scope="col" className="sa:h-8 sa:px-2 sa:text-start sa:font-medium">
            {labels.funnelStage}
          </th>
          {[labels.funnelCount, labels.funnelFromPrevious, labels.funnelFromFirst, labels.funnelDropOffHead].map((head, i) => (
            <th key={i} scope="col" className="sa:h-8 sa:px-2 sa:text-end sa:font-medium sa:whitespace-nowrap">
              {head}
            </th>
          ))}
        </tr>
      </thead>
      <tbody>
        {rows.map((row) => (
          <tr key={row.index}>
            <th scope="row" className={cn(cell, 'sa:text-start sa:font-normal sa:whitespace-normal')}>
              {row.label}
            </th>
            <td className={cell}>{fmt.count(row.value)}</td>
            <td className={cell}>{pct(row.fromPrevious)}</td>
            <td className={cell}>{pct(row.fromFirst)}</td>
            <td className={cell}>
              {row.dropOff == null ? '—' : fmt.count(row.dropOff)}
              {row.bigDropOff && <span className="sa:sr-only">{`, ${labels.funnelBigDropOff}`}</span>}
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  )
}

/* ---------- chart ---------- */

export interface FunnelChartProps extends Omit<ChartCardBaseProps, 'data' | 'formatValue' | 'highlight' | 'range'> {
  stages: FunnelStage[]
  /** The dates the funnel covers, under the title (or the KPI). */
  range?: string
  /** Writes the counts ("€48,000"). Default: the number in `dateLocale`. */
  format?: (value: number) => string
  /**
   * Which conversions to show: from the previous stage (the step under the flow), from
   * the first (after each count), or both. Default 'previous'.
   */
  showConversion?: FunnelConversion
  /** Rows (default) or columns. */
  orientation?: 'horizontal' | 'vertical'
  /** Share of the previous stage lost (0–1) that turns the step amber with a warning icon and adds "big drop-off". Default 0.5. */
  dropOffWarning?: number
  /** Shows the data table under the funnel; it is always in the DOM for screen readers. */
  showTable?: boolean
  /** Skeleton rows at the height of five stages. */
  loading?: boolean
  /** The empty state's title when `stages` is empty. Default "No data". */
  empty?: React.ReactNode
  /** Shows the reason in place of the funnel, read out politely; `true` says "Couldn't load". */
  error?: React.ReactNode | boolean
  /** Adds Retry to the error. */
  onRetry?: () => void
  /** Makes every stage a button. */
  onStageSelect?: (index: number, stage: FunnelStage) => void
  /** Index of the stage shown as hovered (state sheets, docs). */
  highlight?: number
  /** No entrance, as under prefers-reduced-motion. */
  reducedMotion?: boolean
}

// Loading, empty and error keep the loaded funnel's height: horizontal, 8 + 48px of words + 20 (the flow sits a little below them),
// a 160px shape and 32 of steps; vertical, five rows of 88.
const HORIZONTAL_BODY = 'sa:min-h-[268px]'
const VERTICAL_BODY = 'sa:min-h-[440px]'

/**
 * The funnel in its card. See the block comment above for the anatomy, states and keys. Other
 * props, `ref` included, go to the card's root `div`.
 */
export function FunnelChart({
  stages,
  title,
  range = '',
  format,
  showConversion = 'previous',
  orientation = 'horizontal',
  dropOffWarning = 0.5,
  showTable = false,
  loading = false,
  empty,
  error,
  onRetry,
  onStageSelect,
  highlight,
  reducedMotion = false,
  ...props
}: FunnelChartProps) {
  const labels = useLabels()
  const fmt = useFormatters(labels, format)
  const rows = React.useMemo(() => funnelRows(stages, dropOffWarning), [stages, dropOffWarning])
  const failed = !loading && error != null && error !== false
  const ready = !loading && !failed && rows.length > 0
  const vertical = orientation === 'vertical'
  const n = rows.length

  const [hovered, setHovered] = React.useState<number | null>(null)
  const [focused, setFocused] = React.useState<number | null>(null)
  const [tabStop, setTabStop] = React.useState(0)
  // The list's unmount fires no blur or pointer leave: forget the stage on show while it's gone.
  if (!ready && (hovered != null || focused != null)) {
    setHovered(null)
    setFocused(null)
  }
  const stop = Math.min(tabStop, Math.max(0, n - 1))
  const pointer = hovered != null && hovered < n ? hovered : null
  const keyboard = focused != null && focused < n ? focused : null
  const active = !ready ? null : (pointer ?? keyboard ?? (highlight != null && highlight < n ? highlight : null))

  const listRef = React.useRef<HTMLOListElement>(null)
  // Left to right, the card sits after the stage's column, over the next stage's flow: in right to
  // left that is its left. Read when a stage goes on show.
  const [rtl, setRtl] = React.useState(false)
  const showing = active != null
  React.useLayoutEffect(() => {
    if (showing && listRef.current) setRtl(getComputedStyle(listRef.current).direction === 'rtl')
  }, [showing])
  const items = React.useRef<(HTMLElement | null)[]>([])
  const offset = React.useRef<GlidePoint>({ x: 0, y: 0 })
  const updateTooltip = React.useRef<(() => void) | null>(null)
  const marker = React.useCallback(
    () => (active == null ? null : (listRef.current?.querySelectorAll('[data-slot="funnel-chart-marker"]')[active] ?? null)),
    [active],
  )
  const markerRef = React.useRef(marker)
  React.useLayoutEffect(() => {
    markerRef.current = marker
  }, [marker])
  const anchor = React.useMemo(() => glideAnchor(() => markerRef.current(), offset), [])
  // The pointer's moves glide; the keyboard's (and a highlight's) jump.
  useGlide(active, {
    measure: () => {
      const el = marker()
      const box = listRef.current
      if (!el || !box) return null
      const r = el.getBoundingClientRect()
      const b = box.getBoundingClientRect()
      return { x: r.left - b.left, y: r.top - b.top }
    },
    apply: (o) => {
      offset.current = o
      updateTooltip.current?.()
    },
    immediate: pointer == null,
  })

  // A shape fades in when it mounts (the CSS plays once per element), so new values swap in place.
  const enter = !reducedMotion

  const move = (to: number) => {
    const i = Math.max(0, Math.min(n - 1, to))
    setTabStop(i)
    setFocused(i)
    setHovered(null)
    items.current[i]?.focus()
  }
  const onKeyDown = (e: React.KeyboardEvent<HTMLOListElement>) => {
    // Alt+← is the browser's Back; leave modified keys alone.
    if (e.altKey || e.metaKey || e.ctrlKey) return
    const rtl = getComputedStyle(e.currentTarget).direction === 'rtl'
    const next = e.key === 'ArrowDown' || e.key === (rtl ? 'ArrowLeft' : 'ArrowRight')
    const prev = e.key === 'ArrowUp' || e.key === (rtl ? 'ArrowRight' : 'ArrowLeft')
    const from = keyboard ?? stop
    if (next) move(from + 1)
    else if (prev) move(from - 1)
    else if (e.key === 'Home') move(0)
    else if (e.key === 'End') move(n - 1)
    else return
    e.preventDefault()
  }

  const body = vertical ? VERTICAL_BODY : HORIZONTAL_BODY
  const activeRow = active != null ? rows[active] : null

  return (
    <ChartCard title={title} range={range} aria-busy={loading || undefined} data-orientation={orientation} {...props}>
      <div data-slot="funnel-chart" data-state={loading ? 'loading' : failed ? 'error' : n === 0 ? 'empty' : undefined}>
        {/* Mounted before the error comes, so it is announced (a filled region that appears often isn't). */}
        <span role="status" className="sa:sr-only">
          {failed ? (error === true ? labels.funnelError : error) : ''}
        </span>
        {loading ? (
          <div className={cn('sa:flex', vertical ? 'sa:flex-col' : '', body)}>
            <span className="sa:sr-only">{labels.funnelLoading}</span>
            {[0, 1, 2, 3, 4].map((i) => (
              <div
                key={i}
                aria-hidden
                className={cn(
                  'sa:flex sa:min-w-0 sa:flex-1',
                  vertical ? 'sa:h-22 sa:items-center sa:gap-4' : 'sa:flex-col',
                )}
              >
                <div className={cn('sa:flex sa:flex-col sa:gap-2', vertical ? 'sa:w-36 sa:shrink-0' : 'sa:px-3 sa:pt-1 sa:pb-3')}>
                  {/* 4 + 12 + 8 + 24 + 12: the 60px of a column's words. */}
                  <Skeleton animated className="sa:w-16 sa:max-w-full" />
                  <Skeleton animated height={vertical ? 20 : 24} className="sa:w-12 sa:max-w-full" />
                </div>
                <div className={cn('sa:flex sa:items-center sa:justify-center', vertical ? 'sa:h-full sa:flex-1' : 'sa:h-50 sa:px-0.5')}>
                  {/* The funnel's narrowing, roughly, so the skeleton already reads as one. */}
                  <Skeleton
                    animated
                    shape="rect"
                    className="sa:rounded-none"
                    style={vertical ? { width: `${100 - i * 18}%`, height: '100%' } : { height: `${100 - i * 18}%`, width: '100%' }}
                  />
                </div>
              </div>
            ))}
          </div>
        ) : failed ? (
          <div className={cn('sa:flex sa:flex-wrap sa:items-center sa:justify-center sa:gap-2', body)}>
            <p className="sa:flex sa:min-w-0 sa:items-center sa:gap-1.5 sa:text-sm sa:leading-(--sa-text-sm--line-height) sa:text-text-muted">
              <WarningCircle aria-hidden className="sa:size-icon-size-sm sa:shrink-0" />
              <span className="sa:min-w-0">{error === true ? labels.funnelError : error}</span>
            </p>
            {onRetry && (
              <Button size="xs" variant="secondary" onClick={onRetry}>
                {labels.funnelRetry}
              </Button>
            )}
          </div>
        ) : n === 0 ? (
          <div className={cn('sa:flex sa:items-center sa:justify-center', body)}>
            <EmptyState title={empty ?? labels.funnelNoData} />
          </div>
        ) : (
          <>
            <ol
              ref={listRef}
              data-slot="funnel-chart-stages"
              aria-label={title}
              className={cn('sa:relative', vertical ? 'sa:flex sa:flex-col' : 'sa:grid sa:auto-cols-fr sa:grid-flow-col')}
              onKeyDown={onKeyDown}
              onPointerLeave={() => setHovered(null)}
            >
              {rows.map((row) => {
                const i = row.index
                const name = labels.funnelStageName(row.label, fmt.count(row.value), stageDetails(row, labels, fmt, showConversion))
                const stage = (
                  <FunnelChartStage
                    row={row}
                    next={rows[i + 1]}
                    orientation={orientation}
                    showConversion={showConversion}
                    format={format}
                    active={active === i}
                    dimmed={active != null && active !== i}
                    enter={enter}
                  />
                )
                const focusRing =
                  'sa:rounded-md sa:outline-none sa:focus-visible:outline-2 sa:focus-visible:-outline-offset-2 sa:focus-visible:outline-action-focus-ring sa:focus-visible:outline-solid'
                const focusProps = {
                  ref: (el: HTMLElement | null) => {
                    items.current[i] = el
                  },
                  tabIndex: i === stop ? 0 : -1,
                  'aria-label': name,
                  onFocus: () => {
                    setTabStop(i)
                    setFocused(i)
                  },
                  onBlur: () => setFocused(null),
                }
                return onStageSelect ? (
                  <li key={i} className="sa:min-w-0" onPointerEnter={() => setHovered(i)}>
                    <button
                      type="button"
                      {...focusProps}
                      className={cn('sa:block sa:w-full sa:cursor-pointer sa:text-start', focusRing)}
                      onClick={() => onStageSelect(i, stages[i])}
                    >
                      {stage}
                    </button>
                  </li>
                ) : (
                  <li key={i} {...focusProps} className={cn('sa:min-w-0', focusRing)} onPointerEnter={() => setHovered(i)}>
                    {stage}
                  </li>
                )
              })}
            </ol>
            {activeRow && (
              <ChartTooltip
                anchor={anchor}
                updateRef={updateTooltip}
                label={activeRow.label}
                {...tooltipContent(activeRow, labels, fmt)}
                side={vertical ? 'top' : (active === n - 1) !== rtl ? 'left' : 'right'}
                data-tone={activeRow.tone}
              />
            )}
          </>
        )}
        {!loading && !failed && n > 0 && (
          <FunnelTable stages={stages} caption={title} format={format} dropOffWarning={dropOffWarning} visible={showTable} className={showTable ? 'sa:mt-4' : undefined} />
        )}
      </div>
    </ChartCard>
  )
}
